-- Hosbah queries.

-- name: ListMonitorsOfApp :many
-- Team scope: an app's monitors, by name.
SELECT * FROM monitors WHERE app_id = sqlc.arg('app_id') AND team_id = sqlc.arg('team_id') ORDER BY name, id;

-- name: MonitorOfApp :one
-- Team scope: one monitor of an app, by id or by name.
SELECT * FROM monitors
WHERE app_id = sqlc.arg('app_id') AND team_id = sqlc.arg('team_id') AND (id = sqlc.arg('ref')::text OR name = sqlc.arg('ref')::text)
ORDER BY (id = sqlc.arg('ref')::text) DESC LIMIT 1;

-- name: CountMonitorsOfApp :one
SELECT count(*) FROM monitors WHERE app_id = sqlc.arg('app_id') AND team_id = sqlc.arg('team_id');

-- name: InsertMonitor :one
INSERT INTO monitors (team_id, app_id, name, kind, target, expected_status, threshold, window_minutes, interval_seconds, enabled, notify_emails, notify_webhook)
VALUES (sqlc.arg('team_id'), sqlc.arg('app_id'), sqlc.arg('name'), sqlc.arg('kind'), sqlc.arg('target'), sqlc.arg('expected_status'), sqlc.arg('threshold'),
    sqlc.arg('window_minutes'), sqlc.arg('interval_seconds'), sqlc.arg('enabled'), sqlc.arg('notify_emails'), sqlc.arg('notify_webhook'))
RETURNING *;

-- name: UpdateMonitorInTeam :one
-- Team scope: the settings of a monitor (its kind never changes). When reset is set (the rule
-- changed, or the monitor was switched off) what the evaluator learned is forgotten.
UPDATE monitors SET name = sqlc.arg('name'), target = sqlc.arg('target'), expected_status = sqlc.arg('expected_status'), threshold = sqlc.arg('threshold'),
    window_minutes = sqlc.arg('window_minutes'), interval_seconds = sqlc.arg('interval_seconds'), enabled = sqlc.arg('enabled'),
    notify_emails = sqlc.arg('notify_emails'), notify_webhook = sqlc.arg('notify_webhook'),
    state = CASE WHEN sqlc.arg('reset')::boolean THEN 'unknown' ELSE state END,
    last_error = CASE WHEN sqlc.arg('reset')::boolean THEN '' ELSE last_error END,
    consecutive_failures = CASE WHEN sqlc.arg('reset')::boolean THEN 0 ELSE consecutive_failures END,
    last_checked_at = CASE WHEN sqlc.arg('reset')::boolean THEN NULL ELSE last_checked_at END,
    updated_at = now()
WHERE id = sqlc.arg('id') AND team_id = sqlc.arg('team_id')
RETURNING *;

-- name: DeleteMonitorInTeam :execrows
DELETE FROM monitors WHERE id = sqlc.arg('id') AND team_id = sqlc.arg('team_id');

-- name: ClaimDueMonitors :many
-- System scope: the evaluator's claim. A monitor is due when it is enabled and was never checked or
-- was last checked interval_seconds ago. Claiming moves last_checked_at to now under FOR UPDATE SKIP
-- LOCKED, so two API instances never check the same monitor in the same period — and no lock is
-- held while the check itself (an HTTP request) runs.
UPDATE monitors SET last_checked_at = sqlc.arg('now')::timestamptz
WHERE id IN (
    SELECT m.id FROM monitors m
    WHERE m.enabled AND (m.last_checked_at IS NULL OR m.last_checked_at + make_interval(secs => m.interval_seconds) <= sqlc.arg('now')::timestamptz)
    ORDER BY m.last_checked_at NULLS FIRST
    LIMIT sqlc.arg('lim')
    FOR UPDATE SKIP LOCKED)
RETURNING *;

-- name: LockMonitor :one
-- Evaluator (system + team scope): the monitor as it is now, locked while a result is applied.
SELECT * FROM monitors WHERE id = sqlc.arg('id') AND team_id = sqlc.arg('team_id') FOR UPDATE;

-- name: RecordMonitorResult :one
UPDATE monitors SET state = sqlc.arg('state'), last_error = sqlc.arg('last_error'), consecutive_failures = sqlc.arg('consecutive_failures'),
    last_checked_at = sqlc.arg('checked_at')::timestamptz, updated_at = now()
WHERE id = sqlc.arg('id') AND team_id = sqlc.arg('team_id')
RETURNING *;

-- name: ServerMetricsAverage :one
-- The averages behind the cpu | memory | disk monitors: one server's samples in [since, until],
-- CPU weighted by how many heartbeats each row stands for. rows = 0: no data.
SELECT count(*)::bigint AS rows,
    coalesce(sum(cpu_percent * samples) / nullif(sum(samples), 0), 0)::double precision AS cpu,
    coalesce(avg(mem_used::double precision / nullif(mem_total, 0) * 100), 0)::double precision AS memory,
    coalesce(avg(disk_used::double precision / nullif(disk_total, 0) * 100), 0)::double precision AS disk
FROM server_metrics
WHERE server_id = sqlc.arg('server_id') AND team_id = sqlc.arg('team_id')
  AND at >= sqlc.arg('since')::timestamptz AND at <= sqlc.arg('until')::timestamptz;
